/**
 * Write the governance contract's interface where its callers read it.
 *
 * Two components talk to the contracts - the back-office's server sends and
 * authorizes transactions, its console reads them and lets a wallet vote - and
 * each used to carry its own hand-written copy of the ABI and of the
 * contract's enums. They drifted. Now the compiled ABIs and the enums read
 * from the source are written to one generated file per caller, and a test
 * (test/AbiExport.t.sol) fails when the back-office's copy is stale.
 *
 * Usage:
 *   forge build && node scripts/export-abi.js                  # write
 *   node scripts/export-abi.js --check                         # compare only
 *
 * Both refuse an interface that breaks the naming rule for roles.
 */

const fs = require("node:fs");
const path = require("node:path");
const {ENUMS, LIMITS, ROLES} = require("./governance-model");

const ROOT = path.resolve(__dirname, "../..");
const ARTIFACT = path.resolve(
  __dirname,
  "../out/CertificateGovernance.sol/CertificateGovernance.json",
);

const REGISTRY_ARTIFACT = path.resolve(
  __dirname,
  "../out/CertificateRegistry.sol/CertificateRegistry.json",
);

const GENERATED =
  "Generated by contracts/scripts/export-abi.js from contracts/contracts/CertificateGovernance.sol\n" +
  "and CertificateRegistry.sol;\n" +
  "do not edit - change the contract, compile, and run the script again.";

const CONSOLE_NOTICE =
  "This file was written in 2026 by the Faculty of Informatics and Information\n" +
  "Technologies for the Professional License Registry. It is licensed under\n" +
  "the MIT License (see LICENSE).";

const comment = text => text.split("\n").map(line => `// ${line}`).join("\n");

/**
 * The ABI in one order whatever compiled it: entries by type, then name, and
 * every object's keys alphabetical. Forge writes the same ABI as solc in
 * another order, and the copies should change only when the interface does.
 */
function canonical(abi) {
  const sortKeys = value =>
    Array.isArray(value)
      ? value.map(sortKeys)
      : value && typeof value === "object"
        ? Object.fromEntries(Object.keys(value).sort().map(key => [key, sortKeys(value[key])]))
        : value;
  const order = entry => `${entry.type}\u0000${entry.name ?? ""}`;
  return abi.map(sortKeys).sort((x, y) => (order(x) < order(y) ? -1 : order(x) > order(y) ? 1 : 0));
}

function model() {
  const abi = canonical(JSON.parse(fs.readFileSync(ARTIFACT, "utf8")).abi);
  return {
    abi,
    registryAbi: canonical(JSON.parse(fs.readFileSync(REGISTRY_ARTIFACT, "utf8")).abi),
    actionTypes: ENUMS.ActionType,
    policyKinds: ENUMS.PolicyKind,
    adminActions: ENUMS.AdminAction,
    proposalStates: ENUMS.ProposalState,
    standings: ENUMS.Standing,
    roles: ROLES,
    limits: LIMITS,
  };
}

function javascript(m, notice, typed) {
  const exported = (name, value, type) =>
    `export const ${name}${typed && type ? `: ${type}` : ""} = ${JSON.stringify(value, null, 2)}${typed ? " as const" : ""};\n`;
  return [
    comment(notice),
    "//",
    comment(GENERATED),
    "",
    ...(typed ? ["import type {InterfaceAbi} from 'ethers';\n"] : []),
    `export const GOVERNANCE_ABI${typed ? ": InterfaceAbi" : ""} = ${JSON.stringify(m.abi, null, 2)};\n`,
    `export const REGISTRY_ABI${typed ? ": InterfaceAbi" : ""} = ${JSON.stringify(m.registryAbi, null, 2)};\n`,
    "/** The contract's ActionType, PolicyKind, AdminAction, ProposalState and Standing enums, by index. */",
    exported("ACTION_TYPES", m.actionTypes),
    exported("POLICY_KINDS", m.policyKinds),
    exported("ADMIN_ACTIONS", m.adminActions),
    exported("PROPOSAL_STATES", m.proposalStates),
    exported("STANDINGS", m.standings),
    "/** The organisational roles of component 10.2, as the contract numbers them. */",
    exported("ROLES", m.roles),
    "/** The contract's own bounds, in seconds where they are times. */",
    exported("LIMITS", m.limits),
  ].join("\n");
}

function outputs() {
  const m = model();
  return {
    "back-office/web/src/blockchain/certificateGovernanceContract.ts": javascript(m, CONSOLE_NOTICE, true),
    "back-office/shared/governance-contract.ts": javascript(m, CONSOLE_NOTICE, true),
    // JSON holds no comment: the notice and the origin are fields. The
    // contracts' own tests read this copy (test/AbiExport.t.sol).
    "back-office/shared/governance-contract.json":
      JSON.stringify(
        {
          _notice: CONSOLE_NOTICE.replace(/\n/g, " "),
          _generated: GENERATED.replace(/\n/g, " "),
          abi: m.abi,
          registryAbi: m.registryAbi,
          actionTypes: m.actionTypes,
          policyKinds: m.policyKinds,
          adminActions: m.adminActions,
          proposalStates: m.proposalStates,
          standings: m.standings,
          roles: m.roles,
          limits: m.limits,
        },
        null,
        2,
      ) + "\n",
  };
}

/**
 * Parameters that break the naming rule for roles: a role and a set of roles
 * are both uint8 in the ABI (DECISIONS.md D21), so a set is always named
 * `...Mask` and a single role never is. An unnamed return value goes by its
 * function's name.
 */
function misnamedRoles(abi = model().abi) {
  const problems = [];
  const walk = (items, owner) =>
    (items ?? []).forEach(item => {
      const name = item.name || owner;
      if (item.internalType === "RoleSet" && !name.endsWith("Mask")) problems.push(`${name} is a set of roles, so a ...Mask`);
      if (/^Role(\[\])?$/.test(item.internalType ?? "") && name.endsWith("Mask")) problems.push(`${name} is one role, not a ...Mask`);
      walk(item.components, owner);
    });
  for (const entry of abi) {
    walk(entry.inputs, entry.name);
    walk(entry.outputs, entry.name);
  }
  if (!abi.some(entry => JSON.stringify(entry).includes('"internalType":"RoleSet"'))) {
    problems.push("no parameter is a RoleSet: the rule checks nothing");
  }
  return problems;
}

/** Files whose content differs from what the contract gives now. */
function stale() {
  return Object.entries(outputs())
    .filter(([file, content]) => {
      const target = path.join(ROOT, file);
      return !fs.existsSync(target) || fs.readFileSync(target, "utf8") !== content;
    })
    .map(([file]) => file);
}

if (require.main === module) {
  const problems = misnamedRoles();
  if (problems.length) {
    console.error(`The contract's interface breaks the naming rule for roles:\n  ${problems.join("\n  ")}`);
    process.exitCode = 1;
  } else if (process.argv.includes("--check")) {
    const files = stale();
    if (files.length) {
      console.error(`Stale, run node scripts/export-abi.js:\n  ${files.join("\n  ")}`);
      process.exitCode = 1;
    } else {
      console.log("The generated copies match the contract.");
    }
  } else {
    for (const [file, content] of Object.entries(outputs())) {
      fs.writeFileSync(path.join(ROOT, file), content);
      console.log(`wrote ${file}`);
    }
  }
}

module.exports = {outputs, stale, misnamedRoles};
